from datetime import timedelta

def burst(entries, ip, n=3, minutes=2):
    times = sorted(e["time"] for e in failed_logins(entries) if e["ip"] == ip)
    window = timedelta(minutes=minutes)
    for i in range(len(times) - n + 1):
        if times[i + n - 1] - times[i] <= window:
            return True
    return False

attackers = [ip for ip, _ in suspects(entries) if burst(entries, ip)]
